S.ffw_hooks["level_name"] = { id = "level_name", purpose = "Tell the hub from a run so the class picker opens when a run starts", method = "GameplayStatics:GetCurrentLevelName(pc, true)", targets = {"Menu", "MainMenu", "Hub", "Lobby", "Saloon", "Town", "Frontend", "Entry"}, fallback = "none", module = "sys_core", verified = "pending" }
